const K=0.25,R=0.12,HX=3,HY=1.5,MAX=60,TOL=0.01,S0=[2.5,1],SC=0.38;
const loss=(x,y)=>0.5*(x*x+4*y*y);
const out=b=>Math.abs(b.x)>HX||Math.abs(b.y)>HY;
const done=b=>out(b)||loss(b.x,b.y)<TOL;
const word=(b,s)=>out(b)?'diverged':loss(b.x,b.y)<TOL?'converged':s.n>=MAX?'stopped':s.on?'running':'paused';
const ball=()=>({x:S0[0],y:S0[1],p:[S0]});
const fresh=on=>({on,n:0,a:ball(),b:ball()});
const move=(b,lr)=>{if(done(b))return b;const x=b.x-lr*b.x,y=b.y-lr*4*b.y;return{x,y,p:b.p.concat([[x,y]])};};
const over=s=>s.n>=MAX||(done(s.a)&&done(s.b));
const adv=(s,i)=>over(s)?{...s,on:false}:{...s,n:s.n+1,a:move(s.a,i.lrA),b:move(s.b,i.lrB)};
export function initialState(){return fresh(false);}
export function reduce({state:s,event:e,inputs:i}){
 if(e.type==='step')return !s.on||e.tick%6?s:adv(s,i);
 if(e.type==='parameter')return fresh(s.on);
 if(e.type!=='action')return s;
 if(e.action==='run')return over(s)?s:{...s,on:true};
 if(e.action==='pause')return{...s,on:false};
 if(e.action==='stepOnce')return adv({...s,on:false},i);
 return s;
}
const cl=(v,h)=>Math.max(-h,Math.min(h,v));
const pt=p=>{const x=cl(p[0],HX),y=cl(p[1],HY);return[y,K*loss(x,y)+0.03,x];};
function aim(b,lr){
 const dx=-lr*4*b.y,dz=-lr*b.x,v=Math.hypot(dx,dz),h=Math.SQRT1_2;
 if(done(b)||v===0)return{visible:false};
 return{visible:true,position:[dx/v*R,0,dz/v*R],quaternion:[dz/v*h,0,-dx/v*h,h],scale:[1,v*SC,1]};
}
const place=b=>{const x=cl(b.x,HX),y=cl(b.y,HY);return[y,K*loss(x,y)+R,x];};
export function evaluate({inputs:i,state}){
 const s=state||initialState();
 return{nodes:{ballA:{position:place(s.a)},ballB:{position:place(s.b)},arrowA:aim(s.a,i.lrA),arrowB:aim(s.b,i.lrB),trailA:{points:s.a.p.map(pt)},trailB:{points:s.b.p.map(pt)}},
 readouts:{lossA:loss(s.a.x,s.a.y),lossB:loss(s.b.x,s.b.y),steps:s.n,statusA:word(s.a,s),statusB:word(s.b,s)}};
}
